// 实际出生截面的必要年龄门；定点源码夹具不冒18年自然World运行。
#include "resident/domains/family/actor_age_birth_read.hpp"
#include "resident/domains/family/family_birth.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}}
int main(){try{auto catalog=std::make_shared<CommonCatalog>();catalog->family_birth_identity_enabled=true;CommonState initial;initial.identity.tick=18*720+7;initial.next_instance_id=99;ActorRecord child;child.id="actor:2";child.birth_tick=child.created_tick=7;child.prototype_id="newborn";initial.actors.insert(child.id,child);initial.facts.insert("action:1",{"action:1","estate_construction","estate"});initial.facts.insert("family_birth:80",{"family_birth:80","family_birth_recorded","family_birth"});initial.facts.insert(child.id,{child.id,"actor_creation","family_birth"});initial.facts.insert("action:3",{"action:3","estate_construction","estate"});CommonStore common(initial,catalog);FamilyBirthState births;FamilyBirthRecord birth;birth.actor_id=child.id;birth.prototype_id="newborn";birth.tick=7;births.births.insert("family_birth:80",birth);
 auto age=read_actor_age(common,*catalog,births,child.id);check(age.ok&&age.value.adult&&age.value.age_years==18&&age.value.birth_tick==7,"actual recorded newborn reaches exact18 years");catalog->family_birth_identity_enabled=false;check(!read_actor_age(common,*catalog,child.id).ok,"unselected Birth profile cannot read biological creation through generic age entry");catalog->family_birth_identity_enabled=true;auto old=read_actor_age_before_fact(common,*catalog,births,child.id,common.tick()-1,"action:3");check(old.ok&&!old.value.adult,"current adulthood cannot fill yesterday qualification");check(!read_actor_age_before_fact(common,*catalog,births,child.id,common.tick(),"action:1").ok,"before creation cannot reference later newborn");check(!read_actor_age_before_fact(common,*catalog,births,child.id,common.tick(),child.id).ok,"creation itself is not preexisting identity");check(read_actor_age_before_fact(common,*catalog,births,child.id,common.tick(),"action:3").ok,"fact order rather than numeric ID determines source");
 auto saved=common.state().actors.find(child.id)->birth_tick;common.state().actors.find(child.id)->birth_tick=6;check(!read_actor_age(common,*catalog,births,child.id).ok,"forged birthday cannot age newborn early");common.state().actors.find(child.id)->birth_tick=saved;births.births.find("family_birth:80")->tick=6;check(!read_actor_age(common,*catalog,births,child.id).ok,"forged birth payload cannot replace original actor birthday");births.births.find("family_birth:80")->tick=7;auto empty=births;empty.births={};check(!read_actor_age(common,*catalog,empty,child.id).ok,"header alone is not typed birth source");births.births.insert("family_birth:81",birth);check(!read_actor_age(common,*catalog,births,child.id).ok,"duplicate birth source rejected");births.births.erase("family_birth:81");catalog->family_birth_identity_enabled=false;check(!read_actor_age(common,*catalog,births,child.id).ok,"unselected Birth cannot acquire age origin");check(common.state().next_instance_id==99&&common.state().facts.size()==4,"pure age reader neither allocates nor writes sources");std::cout<<"ACTOR_AGE_BIRTH_READ "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
